CREATE TABLE IF NOT EXISTS app_schema_migrations (
    version INTEGER PRIMARY KEY, name TEXT NOT NULL,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now());

-- Revision 1: existing_media_schema
CREATE TABLE IF NOT EXISTS media_files (
    site TEXT NOT NULL,
    content_id TEXT NOT NULL,
    quality TEXT NOT NULL,
    telegram_account_id BIGINT NOT NULL,
    document_id BIGINT NOT NULL,
    access_hash BIGINT NOT NULL,
    file_reference BYTEA NOT NULL,
    origin_peer BYTEA NOT NULL,
    message_id INTEGER NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (site, content_id, quality, telegram_account_id)
);
ALTER TABLE media_files ADD COLUMN IF NOT EXISTS size_bytes BIGINT;
CREATE INDEX IF NOT EXISTS media_files_origin ON media_files
    (telegram_account_id,origin_peer,message_id);




CREATE TABLE IF NOT EXISTS site_accounts (
    id BIGSERIAL PRIMARY KEY,
    site TEXT NOT NULL,
    label TEXT NOT NULL,
    credential_env TEXT NOT NULL,
    subscription TEXT NOT NULL DEFAULT 'free',
    priority INTEGER NOT NULL DEFAULT 0,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    expires_at TIMESTAMPTZ,
    cooldown_until TIMESTAMPTZ,
    UNIQUE (site, label)
);




CREATE TABLE IF NOT EXISTS request_limits (
    telegram_account_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    scope TEXT NOT NULL,
    requested_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (telegram_account_id, user_id, scope)
);




CREATE TABLE IF NOT EXISTS user_link_history (
    telegram_account_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    url_hash TEXT NOT NULL,
    input_url TEXT NOT NULL,
    site TEXT,
    content_id TEXT,
    canonical_url TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    view_count BIGINT NOT NULL DEFAULT 1,
    first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (telegram_account_id, user_id, url_hash)
);
CREATE INDEX IF NOT EXISTS user_link_history_content
    ON user_link_history (telegram_account_id, site, content_id);




CREATE TABLE IF NOT EXISTS user_media_history (
    telegram_account_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    site TEXT NOT NULL,
    content_id TEXT NOT NULL,
    quality TEXT NOT NULL,
    delivery_count BIGINT NOT NULL DEFAULT 1,
    last_method TEXT NOT NULL,
    first_delivered_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_delivered_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (telegram_account_id, user_id, site, content_id, quality)
);




CREATE TABLE IF NOT EXISTS media_catalog (
    telegram_account_id BIGINT NOT NULL,
    site TEXT NOT NULL,
    content_id TEXT NOT NULL,
    metadata JSONB NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (telegram_account_id, site, content_id)
);




CREATE TABLE IF NOT EXISTS media_aliases (
    telegram_account_id BIGINT NOT NULL,
    alias TEXT NOT NULL,
    site TEXT NOT NULL,
    content_id TEXT NOT NULL,
    PRIMARY KEY (telegram_account_id, alias)
);

-- Revision 2: durable_bot_workflow
CREATE TABLE IF NOT EXISTS bot_users (
    telegram_account_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    is_started BOOLEAN NOT NULL DEFAULT FALSE,
    first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (telegram_account_id, user_id)
);




CREATE TABLE IF NOT EXISTS bot_conversations (
    telegram_account_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    chat_id BIGINT NOT NULL,
    state TEXT NOT NULL,
    data JSONB NOT NULL DEFAULT '{}',
    revision BIGINT NOT NULL DEFAULT 1,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (telegram_account_id, user_id, chat_id)
);




CREATE TABLE IF NOT EXISTS download_menus (
    telegram_account_id BIGINT NOT NULL,
    token TEXT NOT NULL,
    user_id BIGINT NOT NULL,
    chat_id BIGINT NOT NULL,
    message_id INTEGER,
    metadata JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (telegram_account_id, token)
);
CREATE INDEX IF NOT EXISTS download_menus_owner
    ON download_menus (telegram_account_id, user_id, chat_id, created_at);

-- Revision 3: streamable_video_references
ALTER TABLE media_files ADD COLUMN IF NOT EXISTS video_streaming BOOLEAN;

-- Revision 4: verified_complete_media
ALTER TABLE media_files ADD COLUMN IF NOT EXISTS verified_complete BOOLEAN NOT NULL DEFAULT FALSE;

-- Revision 5: video_preview_references
ALTER TABLE media_files ADD COLUMN IF NOT EXISTS video_preview BOOLEAN;

-- Revision 6: indexed_video_references
ALTER TABLE media_files ADD COLUMN IF NOT EXISTS video_faststart BOOLEAN;

-- Revision 7: group_lifecycle_and_admission
CREATE TABLE IF NOT EXISTS bot_groups (
    telegram_account_id BIGINT NOT NULL,
    chat_id BIGINT NOT NULL CHECK (chat_id < 0),
    chat_kind TEXT NOT NULL CHECK (chat_kind IN ('group','supergroup')),
    title TEXT,
    username TEXT,
    is_active BOOLEAN,
    is_admin BOOLEAN,
    can_send BOOLEAN,
    added_by_user_id BIGINT CHECK (added_by_user_id > 0),
    added_at TIMESTAMPTZ,
    readded_at TIMESTAMPTZ,
    removed_at TIMESTAMPTZ,
    admin_since TIMESTAMPTZ,
    last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_event_at TIMESTAMPTZ NOT NULL DEFAULT 'epoch',
    last_event_priority INTEGER NOT NULL DEFAULT 0,
    event_cursors JSONB NOT NULL DEFAULT '{}',
    migrated_to BIGINT CHECK (migrated_to < 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (telegram_account_id,chat_id)
);
CREATE INDEX IF NOT EXISTS bot_groups_active ON bot_groups
    (telegram_account_id,chat_id) WHERE is_active;


CREATE TABLE IF NOT EXISTS group_events (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    telegram_account_id BIGINT NOT NULL,
    chat_id BIGINT NOT NULL,
    event_key TEXT NOT NULL,
    kind TEXT NOT NULL,
    actor_id BIGINT CHECK (actor_id > 0),
    occurred_at TIMESTAMPTZ NOT NULL,
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    applied BOOLEAN NOT NULL,
    previous_active BOOLEAN,
    previous_admin BOOLEAN,
    is_active BOOLEAN,
    is_admin BOOLEAN,
    can_send BOOLEAN,
    UNIQUE (telegram_account_id,chat_id,event_key),
    FOREIGN KEY (telegram_account_id,chat_id)
        REFERENCES bot_groups(telegram_account_id,chat_id)
);
CREATE INDEX IF NOT EXISTS group_events_history ON group_events
    (telegram_account_id,chat_id,occurred_at DESC,id DESC);


CREATE TABLE IF NOT EXISTS group_request_limits (
    telegram_account_id BIGINT NOT NULL,
    chat_id BIGINT NOT NULL,
    accepted_at TIMESTAMPTZ[] NOT NULL DEFAULT '{}',
    PRIMARY KEY (telegram_account_id,chat_id),
    FOREIGN KEY (telegram_account_id,chat_id)
        REFERENCES bot_groups(telegram_account_id,chat_id)
);

-- Revision 8: downloaded_file_message_expiry
CREATE TABLE IF NOT EXISTS file_message_expiry (
    telegram_account_id BIGINT NOT NULL,
    chat_id BIGINT NOT NULL,
    message_id INTEGER NOT NULL CHECK (message_id > 0),
    peer BYTEA NOT NULL,
    delete_at TIMESTAMPTZ NOT NULL,
    next_attempt_at TIMESTAMPTZ NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    completed_at TIMESTAMPTZ,
    PRIMARY KEY (telegram_account_id,chat_id,message_id)
);
CREATE INDEX IF NOT EXISTS file_message_expiry_due ON file_message_expiry
    (telegram_account_id,next_attempt_at) WHERE completed_at IS NULL;
CREATE INDEX IF NOT EXISTS file_message_expiry_completed ON file_message_expiry
    (telegram_account_id,completed_at) WHERE completed_at IS NOT NULL;

CREATE INDEX IF NOT EXISTS media_files_origin ON media_files (telegram_account_id,origin_peer,message_id);

-- Revision 9: group_lifecycle_invariants
UPDATE bot_groups SET admin_since=NULL
WHERE is_admin IS NOT TRUE AND admin_since IS NOT NULL;
WITH RECURSIVE lineage AS (
    SELECT telegram_account_id,chat_id,chat_id AS origin_id,ARRAY[chat_id] AS visited
    FROM bot_groups
    UNION ALL
    SELECT target.telegram_account_id,target.chat_id,parent.chat_id,
        array_append(target.visited,parent.chat_id)
    FROM lineage target JOIN bot_groups parent
        ON parent.telegram_account_id=target.telegram_account_id
        AND parent.migrated_to=target.origin_id
    WHERE NOT parent.chat_id=ANY(target.visited)
), first_add AS (
    SELECT DISTINCT ON (target.telegram_account_id,target.chat_id)
        target.telegram_account_id,target.chat_id,event.actor_id
    FROM lineage target JOIN group_events event
        ON event.telegram_account_id=target.telegram_account_id
        AND event.chat_id=target.origin_id
    WHERE event.applied AND event.kind IN ('added','readded') AND event.actor_id IS NOT NULL
    ORDER BY target.telegram_account_id,target.chat_id,event.occurred_at,event.id
)
UPDATE bot_groups target SET added_by_user_id=first_add.actor_id
FROM first_add
WHERE target.telegram_account_id=first_add.telegram_account_id
    AND target.chat_id=first_add.chat_id
    AND target.added_by_user_id IS DISTINCT FROM first_add.actor_id;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid='bot_groups'::regclass AND conname='bot_groups_admin_since_standing'
    ) THEN
        ALTER TABLE bot_groups ADD CONSTRAINT bot_groups_admin_since_standing
            CHECK (is_admin IS TRUE OR admin_since IS NULL);
    END IF;
END $$;
